exception when duplicate_object then null;
end $$;

do $$
begin
  create type public.carp_type as enum ('royal', 'common', 'koi', 'barbo', 'pez-gato', 'black-bass', 'lucio');
exception when duplicate_object then null;
end $$;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

