INSERT INTO "public"."waters" ("id", "name", "short_name", "type", "province", "description", "known_for", "best_season", "difficulty", "image", "tags", "notes", "website", "source", "sort_order", "created_at", "updated_at") VALUES ('don-benito', 'Charca Don Benito', 'Don Benito', 'Charca', 'Badajoz', 'Escenario comodo para pescar rapido, mover cebos dulces y buscar actividad constante a media distancia.', 'Carpas activas y pesca agil', 'Primavera y verano', 'Baja / media', 'storage://team-assets/images/waters/don-benito.png', ARRAY['rapida','dulce','charca'], 'Las mezclas de maiz, particulas y cebos dulces suelen funcionar muy bien cuando el pez se mueve.', '', 'seed', 3, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('don-tello', 'Don Tello', 'Don Tello', 'Rio', 'Badajoz', 'Escenario cambiante, perfecto para leer corrientes, buscar pasos de carpas y apostar por cebos de mucha confianza.', 'Comunes fuertes y pesca cambiante', 'Primavera y otono', 'Alta', 'storage://team-assets/images/waters/don-tello.jpeg', ARRAY['rio','corriente','comunes'], 'La movilidad, el posicionamiento y el trabajo del cebo marcan mucho la diferencia.', '', 'seed', 5, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('gijo', 'Gijo', 'Gijo', 'Rio', 'Badajoz', 'Tramo cambiante para leer actividad, aprovechar pasos de pez y sacar partido a cebos de mucha confianza.', 'Pesca de paso y movilidad', 'Primavera', 'Alta', 'storage://team-assets/images/logo.png', ARRAY['rio','movilidad','paso de pez'], 'Conviene observar mucho el escenario y ajustar rapido tanto el puesto como la presentacion.', '', 'seed', 8, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('horno-tejero', 'Horno Tejero', 'Horno Tejero', 'Embalse', 'Badajoz', '', 'Grandes peces', 'Primavera y otono', 'Alta', 'storage://team-assets/images/uploads/waters/horno-tejero.jpg', ARRAY[], '', '', 'custom', 10, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('las-tijeras', 'Las Tijeras', 'Las Tijeras', 'Charca', 'Badajoz', 'Escenario recogido y muy practico para sesiones cortas, con zonas limpias donde destacan las presentaciones visibles.', 'Jornadas rapidas y montajes visuales', 'Primavera y otono', 'Media', 'storage://team-assets/images/logo.png', ARRAY['sesion corta','charca','visual'], 'Buena opcion para trabajar puestos concretos con cebado medido y montajes limpios.', '', 'seed', 7, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('orellana', 'Embalse de Orellana', 'Orellana', 'Embalse', 'Badajoz', 'Escenario grande y muy visual para sesiones largas, con posibilidades de sacar royales y comunes de mucho porte.', 'Grandes royales y pesca de distancia', 'Primavera y otono', 'Media / alta', 'storage://team-assets/images/waters/orellana.png', ARRAY['grandes peces','sesiones largas','royales'], 'Buen escenario para trabajar zonas de grava, entradas de viento y cebados medidos.', '', 'seed', 1, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('portugal', 'Portugal', 'Portugal', 'Pais / zona', 'Portugal', 'Escenario general para viajes, sesiones fuera de Extremadura y capturas registradas en aguas portuguesas.', 'Viajes y escenarios internacionales', 'Todo el ano', 'Media', 'storage://team-assets/images/logo.png', ARRAY['portugal','viaje','internacional'], 'Pensado para guardar capturas y jornadas cuando solo quieras indicar que la sesion fue en Portugal.', '', 'seed', 9, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('proserpina', 'Embalse de Proserpina', 'Proserpina', 'Embalse', 'Badajoz', 'Agua muy conocida y comoda para plantear jornadas tecnicas, ideal para jugar con pop-ups y presentaciones limpias.', 'Pesca tecnica y cebados cortos', 'Primavera', 'Media', 'storage://team-assets/images/waters/proserpina.png', ARRAY['tecnica','orillas limpias','pop-up'], 'Muy interesante para sesiones cortas bien planteadas y lectura visual del escenario.', '', 'seed', 2, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('sierra-brava', 'Embalse de Sierra Brava', 'Sierra Brava', 'Embalse', 'Caceres', 'Agua grande, potente y con posibilidades de sacar peces muy serios, especialmente cuando se acierta con la zona.', 'Big fish y jornadas maraton', 'Otono e invierno', 'Alta', 'storage://team-assets/images/waters/sierra-brava.png', ARRAY['big fish','embalse','larga distancia'], 'Conviene cebar con precision y mantener una estrategia consistente de varias horas.', '', 'seed', 6, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('valverde', 'Charca Valverde', 'Valverde', 'Charca', 'Badajoz', 'Zona entretenida para montar pescas tacticas y trabajar peces de media entidad con cebos visibles y precisos.', 'Sesiones cortas y royales activas', 'Invierno y primavera', 'Media', 'storage://team-assets/images/waters/valverde.jpeg', ARRAY['royal','charca','sesiones cortas'], 'Ideal para insistir con montajes visuales y cebados muy controlados.', '', 'seed', 4, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00');

