INSERT INTO "public"."brands" ("id", "name", "specialty", "known_for", "featured_products", "description", "image", "url", "source", "sort_order", "created_at", "updated_at") VALUES ('avidcarp', 'Avid Carp', 'Tackle moderno y funcional', 'Equipamiento, montajes y accesorios practicos', ARRAY['Accesorios','Bolsas','Terminal tackle'], 'Avid Carp destaca por un catalogo moderno, orientado a pescadores que quieren material funcional y bien resuelto.', 'storage://team-assets/images/brands/avidcarp.png', 'https://www.avidcarp.com', 'seed', 9, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('daiwa', 'Daiwa', 'Carretes y canas', 'Mecanica de calidad y material contrastado', ARRAY['Carretes','Canas','Accesorios'], 'Daiwa es una marca muy respetada por su trabajo en carretes y canas, con productos muy apreciados por pescadores de distintos niveles.', 'storage://team-assets/images/brands/daiwa.png', 'https://www.daiwa.com', 'seed', 10, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('fox', 'Fox', 'Canas, soportes y material completo', 'Rod pods, canas y accesorios', ARRAY['Canas','Rod pods','Alarmas'], 'Marca muy extendida por ofrecer soluciones completas para sesiones de diferente nivel y presupuesto.', 'storage://team-assets/images/brands/fox.png', 'https://www.foxint.com', 'seed', 3, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('korda', 'Korda', 'Terminal tackle y estrategia', 'Montajes, accesorios y material tecnico', ARRAY['Anzuelos','Lead clips','Accesorios de montaje'], 'Marca muy reconocida por su enfoque tecnico, material de montaje y filosofia de pesca muy cuidada.', 'storage://team-assets/images/brands/korda.png', 'https://kordatackle.com', 'seed', 1, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('nash', 'Nash', 'Equipamiento integral', 'Bivvies, ropa, luggage y tackle', ARRAY['Bivvies','Mochilas','Boilies'], 'Catalogo muy amplio para el carp angler que busca desde equipamiento hasta cebos y textil.', 'storage://team-assets/images/brands/nash.png', 'https://nashtackle.co.uk', 'seed', 2, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('ngt', 'NGT', 'Accesorios y equipamiento asequible', 'Material practico y buena relacion calidad/precio', ARRAY['Rod pods','Sillas','Accesorios'], 'NGT es habitual entre pescadores que buscan material funcional y accesible para montar o ampliar equipo sin complicarse.', 'storage://team-assets/images/brands/ngt.png', 'https://ngtonline.co.uk', 'seed', 12, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('prologic', 'Prologic', 'Equipamiento completo', 'Canas, alarmas, luggage y accesorios', ARRAY['Canas','Alarmas','Bolsas'], 'Prologic ofrece una gama amplia para montar un equipo completo, con propuestas funcionales y una estetica muy reconocible.', 'storage://team-assets/images/brands/prologic.png', 'https://www.prologicfishing.com', 'seed', 11, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('ridgemonkey', 'RidgeMonkey', 'Accesorios inteligentes', 'Cocina de session y gadgets utiles', ARRAY['Sartenes','Luces','Power packs'], 'Muy apreciada por accesorios practicos que mejoran la comodidad durante las jornadas largas.', 'storage://team-assets/images/brands/ridgemonkey.png', 'https://ridgemonkey.co.uk', 'seed', 4, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('shimano', 'Shimano', 'Carretes y mecanica', 'Carretes robustos y suaves', ARRAY['Carretes','Canas','Accesorios'], 'Referente para muchos pescadores cuando buscan carretes fiables y una sensacion de trabajo muy fina.', 'storage://team-assets/images/brands/shimano.png', 'https://fish.shimano.com/es-ES', 'seed', 6, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('solar-tackle', 'Solar Tackle', 'Accesorios tecnicos y equipamiento premium', 'Rod pods, bankware, soportes y accesorios de gran fiabilidad', ARRAY['Rod pods','Bankware','Accesorios'], 'Solar Tackle es una marca muy valorada en carpfishing por la calidad de sus acabados, la resistencia de sus materiales y su enfoque tecnico, es ideal para pescadores que buscan soluciones duraderas y fiables para sesiones exigentes.', 'storage://team-assets/images/brands/solar-tackle.png', 'https://tiendacarpfishing.es/collections/solar', 'seed', 8, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('sonik', 'Sonik', 'Material con gran equilibrio calidad/precio', 'Canas, alarmas y equipamiento', ARRAY['Canas','Alarmas','Sillas'], 'Buena opcion para montar un equipo funcional y moderno sin renunciar a una estetica cuidada.', 'storage://team-assets/images/brands/sonik.png', 'https://www.soniksports.com', 'seed', 5, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('ultimate', 'Ultimate', 'Material accesible y equipamiento completo', 'Canas, carretes, rod pods y accesorios', ARRAY['Canas','Carretes','Rod pods'], 'Ultimate es una marca conocida por ofrecer equipamiento variado y funcional, muy interesante para pescadores que buscan montar un equipo completo con buena relacion calidad/precio.', 'storage://team-assets/images/brands/ultimate.png', 'https://ultimateangling.com/en', 'seed', 7, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00');

