-- Ajuste portable:
-- En un proyecto nuevo, public_url del proyecto antiguo no servira.
-- Dejamos public_url a null y normalizamos source_path como storage://team-assets/<path>.
update public.assets
set
  public_url = null,
  source_path = case
    when bucket is not null and path is not null then 'storage://' || bucket || '/' || path
    else source_path
  end
where bucket = 'team-assets';

commit;

